/**
 * Local webhook signature verification.
 *
 * The REFERENCE_VECTORS below were generated by the Go SDK, which canonicalises with the
 * same `encoding/json` the QBitFlow API itself uses. Asserting against them keeps all four
 * SDKs byte-identical: if this SDK's canonical form or signature ever drifts from Go's,
 * these fail rather than silently rejecting genuine webhooks in production.
 */

import { ValidationException } from '../src/exceptions';
import {
	canonicalJson,
	computeWebhookSignature,
	verifyWebhookSignature,
	extractWebhookHeaders,
	TEST_WEBHOOK_ID,
} from '../src/webhooks/verify';

