const nowTs = () => Math.floor(Date.now() / 1000).toString();

describe('Webhook signature verification', () => {
	describe('cross-SDK reference vectors (generated by the Go SDK)', () => {
		it.each(REFERENCE_VECTORS)(
			'canonicalises $name identically to Go',
			({ input, canonical }) => {
				expect(canonicalJson(input)).toBe(canonical);
			}
		);

		it.each(REFERENCE_VECTORS)('signs $name identically to Go', ({ input, signature }) => {
			expect(computeWebhookSignature(SECRET, TIMESTAMP, input)).toBe(signature);
		});
	});

	describe('golden vectors (Go-generated, per-vector secret and timestamp)', () => {
		it.each(GOLDEN_VECTORS)(
			'canonicalises $name identically to Go',
			({ payload, canonical }) => {
				expect(canonicalJson(payload)).toBe(canonical);
			}
		);

		it.each(GOLDEN_VECTORS)(
			'signs $name identically to Go',
			({ payload, secret, timestamp, signature }) => {
				expect(computeWebhookSignature(secret, timestamp, payload)).toBe(signature);
			}
		);

		it.each(GOLDEN_VECTORS)(
			'verifies $name end to end',
			({ payload, secret, timestamp, signature }) => {
				expect(() =>
					verifyWebhookSignature(secret, timestamp, signature, payload, {
						skipTimestampCheck: true,
					})
				).not.toThrow();
			}
		);
	});

	describe('golden vectors, second set (Go-generated)', () => {
		it.each(GOLDEN_VECTORS_2)(
			'canonicalises "$name" identically to Go',
			({ payload, canonical }) => {
				expect(canonicalJson(payload)).toBe(canonical);
			}
		);

		it.each(GOLDEN_VECTORS_2)(
			'signs "$name" identically to Go',
			({ payload, secret, timestamp, signature }) => {
				expect(computeWebhookSignature(secret, timestamp, payload)).toBe(signature);
				expect(() =>
					verifyWebhookSignature(secret, timestamp, signature, payload, {
						skipTimestampCheck: true,
					})
				).not.toThrow();
			}
		);

		it('produces the same canonical form from raw bytes as from the text', () => {
			for (const { payload, canonical } of GOLDEN_VECTORS_2) {
				expect(canonicalJson(Buffer.from(payload))).toBe(canonical);
				expect(canonicalJson(new TextEncoder().encode(payload))).toBe(canonical);
				expect(canonicalJson(new TextEncoder().encode(payload).buffer)).toBe(canonical);
			}
		});
	});

	describe('canonicalJson', () => {
		it('sorts object keys at every level', () => {
			expect(canonicalJson('{"b":2,"a":1}')).toBe('{"a":1,"b":2}');
			expect(canonicalJson('{"z":{"y":1,"x":2}}')).toBe('{"z":{"x":2,"y":1}}');
		});

		it('preserves array order', () => {
			// Arrays are ordered by definition: sorting them would change meaning.
			expect(canonicalJson('{"items":[3,1,2]}')).toBe('{"items":[3,1,2]}');
		});

		it('drops insignificant whitespace', () => {
			expect(canonicalJson('{\n  "a" : 1 }')).toBe('{"a":1}');
		});

		it('accepts a Buffer, a Uint8Array, an ArrayBuffer, a string, or a parsed object', () => {
			const expected = '{"a":1,"b":2}';
			expect(canonicalJson('{"b":2,"a":1}')).toBe(expected);
			expect(canonicalJson(Buffer.from('{"b":2,"a":1}'))).toBe(expected);
			expect(canonicalJson(new TextEncoder().encode('{"b":2,"a":1}'))).toBe(expected);
			expect(canonicalJson(new TextEncoder().encode('{"b":2,"a":1}').buffer)).toBe(expected);
			expect(canonicalJson({ b: 2, a: 1 })).toBe(expected);
		});

		it('keeps -0 and {} / [] from an already-parsed object, and honours toJSON', () => {
			expect(canonicalJson({ n: -0, o: {}, a: [], d: new Date(0), u: undefined })).toBe(
				'{"a":[],"d":"1970-01-01T00:00:00.000Z","n":-0,"o":{}}'
			);
			expect(canonicalJson(JSON.parse('{"n":-0.0}'))).toBe('{"n":-0}');
		});

		it('rejects invalid JSON, missing payloads and values JSON cannot represent', () => {
			expect(() => canonicalJson('{not json')).toThrow(ValidationException);
			expect(() => canonicalJson(null)).toThrow(ValidationException);
			expect(() => canonicalJson(undefined)).toThrow(ValidationException);
			expect(() => canonicalJson({ n: NaN })).toThrow(ValidationException);
			expect(() => canonicalJson({ n: 1n })).toThrow(ValidationException);
			const circular: Record<string, unknown> = {};
			circular.self = circular;
			expect(() => canonicalJson(circular)).toThrow(ValidationException);
		});
	});

	describe('verifyWebhookSignature', () => {
		const payload = '{"uuid":"pay@abc","txType":"payment"}';

		it('accepts a genuine webhook', () => {
			const ts = nowTs();
			const sig = computeWebhookSignature(SECRET, ts, payload);
			expect(() => verifyWebhookSignature(SECRET, ts, sig, payload)).not.toThrow();
		});

		it('accepts a payload whose keys were reordered in transit', () => {
			// The whole point of canonicalisation.
			const ts = nowTs();
			const sig = computeWebhookSignature(SECRET, ts, '{"a":1,"b":2}');
			expect(() => verifyWebhookSignature(SECRET, ts, sig, '{"b":2,"a":1}')).not.toThrow();
		});

		it('rejects a tampered payload', () => {
			const ts = nowTs();
			const sig = computeWebhookSignature(SECRET, ts, payload);
			expect(() =>
				verifyWebhookSignature(SECRET, ts, sig, '{"uuid":"pay@EVIL","txType":"payment"}')
			).toThrow('signature mismatch');
		});

		it('rejects a tampered timestamp', () => {
			const ts = nowTs();
			const sig = computeWebhookSignature(SECRET, ts, payload);
			const other = (Number(ts) - 30).toString();
			expect(() => verifyWebhookSignature(SECRET, other, sig, payload)).toThrow(
				'signature mismatch'
			);
		});

		it('rejects the wrong secret', () => {
			const ts = nowTs();
			const sig = computeWebhookSignature(SECRET, ts, payload);
			expect(() => verifyWebhookSignature('whsec_wrong', ts, sig, payload)).toThrow(
				'signature mismatch'
			);
		});

		it('rejects a replayed webhook outside the window', () => {
			const old = (Math.floor(Date.now() / 1000) - 600).toString();
			const sig = computeWebhookSignature(SECRET, old, payload);
			expect(() => verifyWebhookSignature(SECRET, old, sig, payload)).toThrow('expired');
		});

		it('rejects a timestamp too far in the future', () => {
			// Guards against a forged future timestamp extending the replay window.
			const future = (Math.floor(Date.now() / 1000) + 600).toString();
			const sig = computeWebhookSignature(SECRET, future, payload);
			expect(() => verifyWebhookSignature(SECRET, future, sig, payload)).toThrow('expired');
		});

		it('honours a custom replay window', () => {
			const old = (Math.floor(Date.now() / 1000) - 600).toString();
			const sig = computeWebhookSignature(SECRET, old, payload);
			expect(() =>
				verifyWebhookSignature(SECRET, old, sig, payload, { maxTimestampAgeSeconds: 1800 })
			).not.toThrow();
		});

		it('parses the timestamp like Go strconv.ParseInt', () => {
			const now = Math.floor(Date.now() / 1000);
			const plus = `+${now}`;
			const sig = computeWebhookSignature(SECRET, plus, payload);
			expect(() => verifyWebhookSignature(SECRET, plus, sig, payload)).not.toThrow();
			for (const bad of ['nope', ` ${now}`, `${now} `, '1e9', '12.5', '0x10', '', '١٢']) {
				expect(() => verifyWebhookSignature(SECRET, bad, 'sha256=abc', payload)).toThrow(
					ValidationException
				);
			}
			// Outside the int64 range Go rejects the value outright.
			expect(() =>
				verifyWebhookSignature(SECRET, '9223372036854775808', 'sha256=abc', payload)
			).toThrow('out of range');
			// Extreme but valid values cannot overflow into the window.
			expect(() =>
				verifyWebhookSignature(SECRET, '-9223372036854775808', 'sha256=abc', payload)
			).toThrow('expired');
		});

		it('treats a replay window <= 0 as the default (300 s)', () => {
			const old = (Math.floor(Date.now() / 1000) - 200).toString();
			const tooOld = (Math.floor(Date.now() / 1000) - 400).toString();
			const sigOld = computeWebhookSignature(SECRET, old, payload);
			const sigTooOld = computeWebhookSignature(SECRET, tooOld, payload);
			for (const maxTimestampAgeSeconds of [0, -5]) {
				expect(() =>
					verifyWebhookSignature(SECRET, old, sigOld, payload, { maxTimestampAgeSeconds })
				).not.toThrow();
				expect(() =>
					verifyWebhookSignature(SECRET, tooOld, sigTooOld, payload, {
						maxTimestampAgeSeconds,
					})
				).toThrow('expired');
			}
		});

		it('rejects empty or malformed signatures', () => {
			const ts = nowTs();
			for (const bad of ['', 'sha256=', 'deadbeef', 'sha512=abc']) {
				expect(() => verifyWebhookSignature(SECRET, ts, bad, payload)).toThrow();
			}
		});
	});

	describe('extractWebhookHeaders', () => {
		it('reads a plain Node headers object case-insensitively', () => {
			const h = extractWebhookHeaders({
				'x-webhook-signature-256': 'sha256=abc',
				'X-Webhook-Timestamp': '1700000000',
				'x-webhook-id': 'pay@abc',
			});
			expect(h.signature).toBe('sha256=abc');
			expect(h.timestamp).toBe('1700000000');
			expect(h.webhookId).toBe('pay@abc');
			expect(h.isTest).toBe(false);
		});

		it('reads a Fetch API Headers instance', () => {
			const h = extractWebhookHeaders(
				new Headers({
					'X-Webhook-Signature-256': 'sha256=abc',
					'X-Webhook-Timestamp': '1700000000',
					'X-Webhook-Id': TEST_WEBHOOK_ID,
				})
			);
			expect(h.signature).toBe('sha256=abc');
			expect(h.isTest).toBe(true);
		});

		it('takes the first value when a header repeats', () => {
			const h = extractWebhookHeaders({
				'x-webhook-timestamp': ['1700000000', '1700000001'],
			});
			expect(h.timestamp).toBe('1700000000');
		});

		it('returns empty strings for missing headers', () => {
			const h = extractWebhookHeaders({});
			expect(h.signature).toBe('');
			expect(h.timestamp).toBe('');
			expect(h.isTest).toBe(false);
		});
	});
});
